-- ===========================================================================
-- Boxes · Catálogo de productos
-- ===========================================================================
-- GENERADO por scripts/generate-sql. No editar a mano: se regenera con
-- `npm run sql:generate` y cualquier cambio manual se pierde.
--
-- Va después del 09 y de `node scripts/seed-tiendas.mjs`: necesita el esquema
-- completo y la tienda ya creada. El archivo lo comprueba y avisa si falta algo.
-- 
-- 435 productos importados del Excel de 2025 (Hoja2), a la tienda "Jose's Market".
-- 37 tienen costo real de factura; 398 lo tienen estimado
-- en precio x 0.81 (el margen del 19% de la contabilidad) y están marcados
-- con cost_is_estimated = true.
-- 
-- Primero se crean las 19 categorías y después los productos, que la
-- buscan por nombre. La MARCA queda vacía en los 435: el Excel no la traía y
-- no se inventa. Se va llenando a mano o al escanear el código de barras.
-- 
-- stock queda en 0 en todos: el Excel nunca llevó inventario. Hay que contar.
-- barcode queda vacío por la misma razón.
-- 
-- Volver a correr este archivo no duplica ni pisa nada (on conflict do nothing).
-- Para reimportar el catálogo desde cero: delete from public.products; y correr de nuevo
-- (ojo: eso borra el stock contado y deja las ventas viejas sin producto asociado).
-- ===========================================================================

do $guard$
begin
  if to_regclass('public.tiendas') is null then
    raise exception 'Falta el esquema multi-tienda. Correr supabase/sql/06_tiendas.sql y las que siguen.';
  end if;
  if to_regclass('public.categories') is null then
    raise exception 'Faltan las categorías. Correr supabase/sql/09_categorias_y_marcas.sql.';
  end if;
  if not exists (
    select 1 from public.tiendas
    where lower(btrim(nombre)) = lower(btrim('Jose''s Market'))
  ) then
    raise exception 'No existe la tienda % en esta base. Correr antes: node scripts/seed-tiendas.mjs', 'Jose''s Market';
  end if;
end
$guard$;

insert into public.categories (tienda_id, name)
select t.id, c.name::text
from public.tiendas t
cross join (values
  ('Aceites'),
  ('Aseo del Hogar'),
  ('Bebés'),
  ('Bebidas'),
  ('Cigarrillos'),
  ('Cuidado Personal'),
  ('Desechables'),
  ('Dulces y Chocolates'),
  ('Enlatados'),
  ('Galletas'),
  ('Granos y Abarrotes'),
  ('Hogar y Varios'),
  ('Lácteos'),
  ('Licores'),
  ('Mascotas'),
  ('Panadería'),
  ('Papelería'),
  ('Salud y Farmacia'),
  ('Snacks')
) as c (name)
where lower(btrim(t.nombre)) = lower(btrim('Jose''s Market'))
on conflict do nothing;

insert into public.products (id, tienda_id, name, sku, barcode, photo, price, cost_price, cost_is_estimated, stock, category_id, description, created_at)
select
  v.id::uuid,
  t.id,
  v.name::text,
  v.sku::text,
  v.barcode::text,
  v.photo::text,
  v.price::numeric,
  v.cost_price::numeric,
  v.cost_is_estimated::boolean,
  v.stock::numeric,
  c.id,
  v.description::text,
  v.created_at::timestamptz
from public.tiendas t
cross join (values
  ('88671d8a-9ce2-522d-9f20-9e765672d393', 'Aceite Diana 2000ml', 'ACE-001', '', null::text, 18635, 15094, true, 0, 'Aceites', 'Aceites. Presentación de 2000ml. Costo estimado en 81% del precio de venta (margen del 19% que usa la contabilidad); confirmar con factura. Nombre normalizado desde el Excel; en el archivo original figura como «ACEITE DIANA 2000ML». Revisar que la corrección sea correcta.', '2025-01-01T00:00:00Z'),
