left join public.categories c
  on c.tienda_id = t.id
 and lower(btrim(c.name)) = lower(btrim(v.category))
where lower(btrim(t.nombre)) = lower(btrim('Jose''s Market'))
on conflict do nothing;

insert into public.products (id, tienda_id, name, sku, barcode, photo, price, cost_price, cost_is_estimated, stock, category_id, description, created_at)
select
  v.id::uuid,
  t.id,
  v.name::text,
  v.sku::text,
  v.barcode::text,
  v.photo::text,
  v.price::numeric,
  v.cost_price::numeric,
  v.cost_is_estimated::boolean,
  v.stock::numeric,
  c.id,
